.pf-game dialog.pf-entry{position:fixed!important;inset:0!important;margin:auto!important;box-sizing:border-box;width:min(560px,calc(100vw - 32px))!important;max-width:none!important;height:fit-content!important;max-height:calc(100dvh - 32px - env(safe-area-inset-top) - env(safe-area-inset-bottom))!important;padding:28px!important;border:1px solid #bdc9b8!important;border-radius:22px!important;background:#fff9e8!important;color:#243e38!important;box-shadow:0 18px 70px #173b3f40!important;overflow:auto!important;overscroll-behavior:contain;touch-action:pan-y;text-align:left!important;font-family:Arial,'Noto Sans TC',system-ui,sans-serif!important;transform:none!important;z-index:1000;}
.pf-game dialog.pf-entry:not([open]){display:none!important;}
.pf-game dialog.pf-entry[open]{display:block!important;}
.pf-game dialog.pf-entry::backdrop{background:#173b3f80;backdrop-filter:blur(4px);}
.pf-entry-backdrop{position:fixed;inset:0;background:#173b3f80;backdrop-filter:blur(4px);z-index:999;}
.pf-game .pf-entry .pf-entry-brand{font-size:13px!important;letter-spacing:2px;color:#64796a;margin:0 0 12px!important;}
.pf-game .pf-entry h2{font-size:30px!important;line-height:1.3!important;font-weight:800!important;margin:0 0 18px!important;letter-spacing:0!important;overflow-wrap:anywhere;}
.pf-game .pf-entry .pf-entry-goal,.pf-game .pf-entry .pf-entry-operation{font-size:18px!important;line-height:1.6!important;margin:0 0 16px!important;display:block!important;color:#243e38!important;}
.pf-game .pf-entry .pf-entry-goal{font-weight:700;}
.pf-game .pf-entry details{margin:16px 0!important;font-size:16px!important;line-height:1.6!important;}
.pf-game .pf-entry summary{min-height:44px;display:flex;align-items:center;font-size:16px!important;cursor:pointer;}
.pf-game .pf-entry details p,.pf-game .pf-entry details li{font-size:16px!important;line-height:1.6!important;}
.pf-game .pf-entry a{color:inherit;overflow-wrap:anywhere;}
.pf-game .pf-entry .pf-entry-start{display:block;width:100%;min-height:52px!important;margin:20px 0 0!important;padding:12px 18px!important;background:#27674f!important;color:#fff9e8!important;border:1px solid #27674f!important;border-radius:12px!important;font:700 18px/1.4 Arial,'Noto Sans TC',system-ui,sans-serif!important;cursor:pointer;}
.pf-game .pf-entry .pf-entry-start:disabled{opacity:.5;cursor:not-allowed;}
.pf-game .pf-entry :focus-visible{outline:3px solid #db884b;outline-offset:3px;}

/* Visible recovery while modules initialize; not a playable legacy intro. */
.pf-game .pf-entry-loading{max-width:560px;margin:12px auto;padding:12px 16px;font:400 18px/1.6 Arial,'Noto Sans TC',sans-serif;color:#243e38;background:#fff9e8;border:1px solid #bdc9b8;border-radius:12px}.pf-game .pf-entry-loading a{color:inherit;text-decoration:underline}

/* A suspended underlying view cannot compete with the single help owner. */
.pf-game [data-pf-help-suspended]{display:none!important}
.pf-game .pf-header nav .pf-entry-help{min-width:72px!important;min-height:44px!important;white-space:nowrap;flex-shrink:0}
.pf-game .pf-entry .audio-settings{font-size:18px;line-height:1.5}.pf-game .pf-entry .audio-settings button,.pf-game .pf-entry .audio-settings input{min-height:44px}

.pf-game .pf-pause-help{min-height:44px;min-width:72px;font:700 18px/1.4 Arial,sans-serif;display:block;margin:12px auto;padding:10px 16px;border:1px solid #bdc9b8;border-radius:10px;background:#fff9e8;color:#243e38}.pf-game .pf-pause-help[hidden]{display:none!important}
/* Home stays reachable: actions get their own bounded row on narrow screens. */
@media(max-width:640px){
 .pf-game .pf-header{grid-template-columns:auto minmax(0,1fr);gap:4px 8px}
 .pf-game .pf-header .pf-home{grid-column:1;grid-row:1}
 .pf-game .pf-header h1{grid-column:2;grid-row:1;padding:0;font-size:16px}
 .pf-game .pf-header nav{grid-column:1/-1;grid-row:2;display:grid;grid-template-columns:repeat(3,minmax(0,1fr)) 72px;width:100%;min-width:0;gap:4px}
 .pf-game .pf-header nav button{min-width:0;width:100%;padding:4px;white-space:normal;line-height:1.2}
 .pf-game .pf-header nav .pf-entry-help{min-width:72px!important;white-space:nowrap}
}

