.pf-game .pf-result-dialog h2{font-size:24px;line-height:1.4;margin:12px 0;overflow-wrap:anywhere;}.pf-game .pf-result-dialog p{font-size:14px;line-height:1.55;}.pf-game .pf-result-dialog .result-foot{display:block;font-size:11px;}.pf-game .pf-result-dialog .scoreline strong{font-size:58px;letter-spacing:-2px;}.pf-game .pf-result-dialog .result-mini{display:flex;font-size:12px;}.pf-game .pf-result-dialog .result-mini b{display:block;font-size:18px;}.pf-game .pf-result-dialog .judge-scores b{font-size:22px;}.pf-game .pf-result-dialog .platform-share-note{display:block;font-size:12px;line-height:1.5;}.pf-game .pf-result-dialog #resultPhoto{display:block;width:100%;height:auto;max-height:260px;object-fit:contain;border-radius:12px;background:#20372b;}.pf-game .pf-result-dialog #resultPhoto[hidden]{display:none;}
