.pf-game :is(.card.result,#overlay.result) button{min-height:44px;}

.pf-game .pf-header .pf-audio-status{position:static;inset:auto;grid-column:1/-1;max-width:none;min-width:0;z-index:auto;margin:0;padding:2px 8px;text-align:right;font-size:11px;line-height:1.4;overflow-wrap:anywhere;}

.pf-game .pf-result-dialog [tabindex="-1"]:focus{outline:2px solid currentColor;outline-offset:4px;}

/* Result hierarchy: play actions stay outside optional secondary statistics. */
.pf-game .pf-result-details{grid-column:1/-1;margin:12px 0;border:1px solid #bfcbbd;border-radius:12px;padding:0 12px;min-width:0;text-align:left;}
