.pf-game .pf-result-play{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0;}
.pf-game .pf-result-play>button{flex:1 1 150px;min-height:44px;margin:0;}
.pf-game.pf-reaction-rod #againBtn{min-height:48px;}
.pf-game .pf-result-details :is(.result-stats>div>span,.judge-scores span,.result-mini>span){font-size:14px;line-height:1.5;overflow-wrap:anywhere;}
/* Optional entry details stay readable and easy to open without crowding core controls. */
.pf-game .entry-help{grid-column:1/-1;text-align:left;}
.pf-game .entry-help>summary{min-height:44px;display:flex;align-items:center;font-size:14px;line-height:1.5;cursor:pointer;}
.pf-game .entry-help p{font-size:14px;line-height:1.6;display:block;}
.pf-game [data-entry-operation]{font-size:18px!important;line-height:1.6!important;}
.pf-game [data-entry-operation] :is(b,strong,span){font-size:inherit;line-height:inherit;}
.pf-game #center:has([data-entry-goal]){overflow:auto;justify-content:flex-start;touch-action:pan-y;}
.pf-game #center:has([data-entry-goal])>[data-entry-goal]{margin-top:auto;}
.pf-game #center:has([data-entry-goal])>#start{margin-bottom:auto;flex-shrink:0;}

// A help visit owns presentation, not simulation. Game adapters own safe pausing.
const owners=new WeakSet();
export const helpIsOpen=document=>owners.has(document);
export function createHelpCoordinator(document,suspend=()=>{}){
 let restore=null,active=false;
 return{get active(){return active;},enter(){if(active)return;active=true;owners.add(document);try{restore=suspend()||null;}catch(error){active=false;owners.delete(document);throw error;}},leave({restoreView=true}={}){if(!active)return;active=false;owners.delete(document);const resumeView=restore;restore=null;if(restoreView)resumeView?.();}};
}
// Close via the owning controller so fallback inert/backdrop bookkeeping is restored.
// Panels keep a CSS suspension marker because game UI refreshes may update hidden.
export function suspendHelpPresentation(document,{pause=()=>{},controllers={},dialogs=[],panels=[],after=()=>{}}={}){
 pause();
 const opened=dialogs.map(id=>document.getElementById(id)).filter(node=>node?.open);
 const saved=opened.map(node=>({node,focus:node.contains(document.activeElement)?document.activeElement:null,scroll:node.scrollTop}));
 for(const{node}of [...saved].reverse()){const owner=controllers[node.id];if(owner)owner.close();else node.close();}
 const panelState=panels.filter(Boolean).map(node=>({node,hidden:node.hidden}));for(const{node}of panelState)node.setAttribute('data-pf-help-suspended','');
 return()=>{for(const{node,hidden}of panelState){node.removeAttribute('data-pf-help-suspended');node.hidden=hidden;}for(const{node,focus,scroll}of saved){const owner=controllers[node.id];if(owner)owner.open();else node.showModal();node.scrollTop=scroll;focus?.focus({preventScroll:true});}after({restoredDialog:saved.length>0});};
