test('Hurdles real controller toolbar pauses countdown, clears held input, resumes and restarts',()=>{const a=boot();assert.equal(a.els.pause.disabled,true);a.startEntry();assert.equal(a.els.pause.disabled,false);a.evaluate("input.key('KeyA',true)");a.els.pause.onclick();assert.equal(a.els.pause.getAttribute('aria-pressed'),'true');assert.equal(a.evaluate('input.values.some(Boolean)'),false);const before=a.evaluate('JSON.stringify(s)');a.frame(2000);assert.equal(a.evaluate('JSON.stringify(s)'),before);a.startEntry();assert.equal(a.els.pause.getAttribute('aria-pressed'),'false');a.els.reset.onclick();assert.equal(a.evaluate('s.t'),0);assert.equal(a.evaluate('paused'),false);});
test('Hurdles music button is a real toggle, not the old settings launcher',async()=>{const a=boot();a.els.sound.onclick();await Promise.resolve();assert.equal(a.audio().ready,true);assert.equal(a.els.sound.getAttribute('aria-pressed'),'true');assert.equal(a.els.settings.open,false);a.els.sound.onclick();await Promise.resolve();assert.equal(a.audio().enabled,false);assert.equal(a.els.sound.getAttribute('aria-pressed'),'false');});
test('Hurdles failed PNG encoding offers regenerate without changing finished score',()=>{const a=boot({failedBlob:true});a.evaluate("s.phase='done';finish()");assert.equal(a.els['save-image'].disabled,false);assert.match(a.els['save-image'].textContent,/重做/);const before=a.evaluate('JSON.stringify(s)');a.setBlobFailure(false);a.els['save-image'].onclick();assert.equal(a.evaluate('resultFile.type'),'image/png');assert.equal(a.evaluate('JSON.stringify(s)'),before);});
test('Hurdles rejects duplicate native shares, cancellation unlocks retry and restart guards completion',async()=>{let finish,calls=0;const a=boot({shareFn:()=>{calls++;return new Promise((_,reject)=>finish=reject);}});a.evaluate("s.phase='done';finish()");const pending=a.els['save-image'].onclick();assert.equal(a.els['save-image'].disabled,true);await a.els['save-image'].onclick();assert.equal(calls,1);finish(Object.assign(Error('cancel'),{name:'AbortError'}));await pending;assert.equal(a.els['save-image'].disabled,false);const again=a.els['save-image'].onclick();a.els.reset.onclick();finish(Object.assign(Error('cancel'),{name:'AbortError'}));await again;assert.equal(a.els['share-status'].textContent,'');assert.equal(a.evaluate('resultFile'),null);});

function resultWithTail(a){a.evaluate("start();for(let i=0;i<=10;i++){s.t=5+i*.5;s.x=100+i;if(i===10)s.phase='done';replay.record(s);}finish();");}
test('Hurdles replay is opt-in, preserves exact result/photo/PNG/best and never simulates or captures again',()=>{
 const a=boot();resultWithTail(a);assert.equal(a.evaluate('replay.active'),false);assert.equal(a.els.overlay.open,true);assert.equal(a.els['replay-last'].hidden,false);const before=a.evaluate('JSON.stringify(s)'),photo=a.els['finish-frame'].children[0],file=a.evaluate('resultFile'),run=a.evaluate('runId'),counts={capture:a.calls.capture,card:a.calls.card,storage:a.calls.storage};a.els.overlay.scrollTop=123;
 a.els['replay-last'].onclick();assert.equal(a.evaluate('replay.active'),true);assert.equal(a.els.overlay.open,false);assert.equal(a.els['replay-panel'].hidden,false);assert.equal(a.doc.activeElement,a.els['replay-return']);a.frame(50);assert.ok(a.evaluate('replay.time')>5);assert.equal(a.evaluate('JSON.stringify(s)'),before);
 for(let i=0;i<70;i++)a.frame(100);assert.equal(a.evaluate('replay.active'),false);assert.equal(a.els.overlay.open,true);assert.equal(a.els['replay-panel'].hidden,true);assert.equal(a.els['finish-frame'].children[0],photo);assert.equal(a.evaluate('resultFile'),file);assert.equal(a.evaluate('runId'),run);assert.equal(a.els.overlay.scrollTop,123);assert.equal(a.doc.activeElement,a.els['replay-last']);assert.deepEqual({capture:a.calls.capture,card:a.calls.card,storage:a.calls.storage},counts);assert.equal(a.calls.renders.some(r=>r.points&&r.state.phase==='done'),true);assert.equal(a.evaluate('JSON.stringify(s)'),before);
});
test('Hurdles replay pause/background/cancel/repeat/resize and restart keep clocks and keys safe',()=>{
 const a=boot();resultWithTail(a);a.els['replay-last'].onclick();a.frame(50);a.els.pause.onclick();const t=a.evaluate('replay.time');a.frame(5000);assert.equal(a.evaluate('replay.time'),t);assert.equal(a.els.pause.getAttribute('aria-pressed'),'true');a.els.pause.onclick();a.frame(50);assert.ok(a.evaluate('replay.time')>t);a.doc.hidden=true;a.doc.handlers.visibilitychange[0]();const bg=a.evaluate('replay.time');a.frame(5000);assert.equal(a.evaluate('replay.time'),bg);a.doc.hidden=false;a.els.pause.onclick();a.evaluate('innerWidth=844;innerHeight=390;visualViewport.width=844;visualViewport.height=390;layout()');assert.equal(a.evaluate('replay.paused'),true);
 a.els['replay-return'].onclick();assert.equal(a.els.overlay.open,true);a.els['replay-last'].onclick();assert.equal(a.evaluate('replay.time'),5);a.evaluate("input.key('KeyA',true)");a.els.reset.onclick();assert.equal(a.evaluate('replay.active'),false);assert.equal(a.evaluate('replay.ready'),false);assert.equal(a.evaluate('s.t'),0);assert.equal(a.evaluate('input.values.some(Boolean)'),false);assert.equal(a.els['replay-panel'].hidden,true);
});
