test('Hurdles pending PNG finishes during replay without re-encoding and stale restart callback cannot overwrite next round',()=>{
 const a=boot({deferredBlob:true});resultWithTail(a);assert.equal(a.calls.blobs.length,1);assert.equal(a.evaluate('resultFile'),null);const before=a.evaluate('JSON.stringify(s)');a.els['replay-last'].onclick();a.calls.blobs.shift()(new Blob(['first png'],{type:'image/png'}));const file=a.evaluate('resultFile');assert.equal(file.type,'image/png');assert.equal(a.calls.card,1);a.els['replay-return'].onclick();assert.equal(a.evaluate('resultFile'),file);assert.equal(a.evaluate('JSON.stringify(s)'),before);
 a.els.reset.onclick();resultWithTail(a);a.els['replay-last'].onclick();const stale=a.calls.blobs.shift();a.els.reset.onclick();stale(new Blob(['stale png'],{type:'image/png'}));assert.equal(a.evaluate('resultFile'),null);assert.equal(a.els['share-status'].textContent,'');
});

