test('Hurdles software replay pause uses the idle draw cadence rather than continuously rasterizing',()=>{const a=boot({software:true});resultWithTail(a);a.els['replay-last'].onclick();a.els.pause.onclick();const n=a.calls.renders.length;for(let i=0;i<10;i++)a.frame(20);assert.ok(a.calls.renders.length-n<=1);});

